changeSet.sql:
create or alter function [dbo].[GetCombinedPermissionsForUserByAssetUid] 
(
	@uid uniqueidentifier,
	@userId int
)
returns int
as
begin
	declare @id bigint,
			@combinedPermissionMask int = 0;
	select	@id = ID from dbo.Asset where Uid = @uid;
	select	@combinedPermissionMask = dbo.GetCombinedPermissionsForUserByAssetId(@id, @userId);
	return	@combinedPermissionMask;
end
